#!/usr/bin/env python3
"""Merge user data from three sources with different formats and schemas.

Sources (priority order):
  1. /data/source_a/users.json   (primary, highest priority)
  2. /data/source_b/users.csv    (secondary)
  3. /data/source_c/users.parquet (tertiary)

Field mapping (different names, same meaning):
  user_id, id, userId            -> user_id
  email, email_address           -> email
  full_name, name, userName      -> name
  registration_date, created_at, joined -> created_date
  status                         -> status (pass-through from source_a)

Outputs:
  /app/merged_users.parquet  - one row per unique user
  /app/conflicts.json        - conflict report
"""

import json

import pandas as pd

SOURCE_A = "/data/source_a/users.json"
SOURCE_B = "/data/source_b/users.csv"
SOURCE_C = "/data/source_c/users.parquet"
OUT_PARQUET = "/app/merged_users.parquet"
OUT_CONFLICTS = "/app/conflicts.json"

# Mapping of original field names to unified field names.
FIELD_MAP = {
    # user id
    "user_id": "user_id",
    "id": "user_id",
    "userId": "user_id",
    # email
    "email": "email",
    "email_address": "email",
    # name
    "full_name": "name",
    "name": "name",
    "userName": "name",
    # created date
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
    # status (source_a already uses the unified name)
    "status": "status",
}

UNIFIED_FIELDS = ["user_id", "name", "email", "created_date", "status"]
PRIORITY = ["source_a", "source_b", "source_c"]


def normalize_value(field, value):
    """Normalize a raw value for a unified field."""
    if value is None or (not isinstance(value, str) and pd.isna(value)):
        return None
    if field == "user_id":
        return int(value)
    if field == "created_date":
        # Ensure YYYY-MM-DD format regardless of input representation.
        return pd.to_datetime(value).strftime("%Y-%m-%d")
    return value


def normalize(record):
    """Map a raw record to the unified schema, dropping unmapped fields."""
    out = {}
    for key, value in record.items():
        field = FIELD_MAP.get(key)
        if field is None:
            continue
        if field in out:
            continue
        out[field] = normalize_value(field, value)
    return out


def to_records(df):
    return [normalize(dict(row)) for _, row in df.iterrows()]


def main():
    with open(SOURCE_A) as f:
        a_records = [normalize(r) for r in json.load(f)]
    b_records = to_records(pd.read_csv(SOURCE_B))
    c_records = to_records(pd.read_parquet(SOURCE_C))

    sources = {
        "source_a": a_records,
        "source_b": b_records,
        "source_c": c_records,
    }

    # Index records of each source by user_id.
    by_user = {
        name: {r["user_id"]: r for r in recs if r.get("user_id") is not None}
        for name, recs in sources.items()
    }

    all_ids = sorted(set().union(*[set(m) for m in by_user.values()]))

    # Merge: for each user and field, the highest-priority source that
    # provides a non-null value wins.
    merged = {}
    for uid in all_ids:
        row = {"user_id": uid}
        for field in UNIFIED_FIELDS[1:]:
            row[field] = None
            for src in PRIORITY:
                rec = by_user[src].get(uid)
                if rec is not None and rec.get(field) is not None:
                    row[field] = rec[field]
                    break
        merged[uid] = row

    # Conflict detection: a conflict exists when the same user has the
    # field present in two or more sources with differing values.
    conflicts = []
    for uid in all_ids:
        for field in UNIFIED_FIELDS:
            values = {}
            for src in PRIORITY:
                rec = by_user[src].get(uid)
                if rec is not None and rec.get(field) is not None:
                    values[src] = rec[field]
            if len(set(values.values())) > 1:
                conflicts.append(
                    {
                        "user_id": uid,
                        "field": field,
                        "values": values,
                        "selected": merged[uid][field],
                    }
                )

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open(OUT_CONFLICTS, "w") as f:
        json.dump(report, f, indent=2)

    df = pd.DataFrame([merged[uid] for uid in all_ids], columns=UNIFIED_FIELDS)
    df["user_id"] = df["user_id"].astype("int64")
    for col in ["name", "email", "created_date", "status"]:
        df[col] = df[col].astype("object")
    df.to_parquet(OUT_PARQUET, index=False)

    print(f"Wrote {len(df)} unique users to {OUT_PARQUET}")
    print(f"Wrote {len(conflicts)} conflicts to {OUT_CONFLICTS}")
    print(df.to_string())
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()

